'use strict';

let base = {};
try { base = $('Set | Scheduler Constants | StateScheduler').first().json || {}; } catch {}
const clean = value => String(value ?? '').normalize('NFKC').trim();
const rows = $input.all().flatMap(item => {
  const value = item?.json?.body ?? item?.json ?? {};
  return Array.isArray(value) ? value : (Array.isArray(value?.data) ? value.data : [value]);
});

return rows.filter(row => row &&
  /^[0-9a-f-]{36}$/.test(clean(row.plan_id ?? row.planId)) &&
  /^[0-9a-f-]{36}$/.test(clean(row.lease_token ?? row.leaseToken)) &&
  Number.isSafeInteger(Number(row.plan_version ?? row.planVersion)) &&
  clean(row.delivery_address ?? row.deliveryAddress) &&
  /^\d{4}-\d{2}-\d{2}$/.test(clean(row.planned_for ?? row.plannedFor)) &&
  clean(row.summary) && /^[0-9a-f]{32}$/.test(clean(row.callback_token ?? row.callbackToken))
).map(row => {
  const planId = clean(row.plan_id ?? row.planId);
  const planVersion = Number(row.plan_version ?? row.planVersion);
  const beginRpcBody = {
    p_plan_id: planId,
    p_lease_token: clean(row.lease_token ?? row.leaseToken),
    p_expected_version: planVersion,
    p_send_key: `future_plan_prompt:${planId}:v${planVersion}`
  };
  return { json: {
    ...base,
    ...row,
    stateFuturePlanClaim: row,
    stateFuturePlanReady: true,
    stateFuturePlanContractVersion: 'chelsea_state_future_plan_claim_v1',
    stateFuturePlanBeginRpcBody: beginRpcBody,
    stateRpcBody: beginRpcBody
  } };
});

'use strict';

const source = $('Code | Normalize Future Plan Claims | FuturePlanFollowUp').item.json || {};
const incoming = $input.first()?.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const expectedPlanId = String(source.stateRpcBody?.p_plan_id || '');
const expectedSendKey = String(source.stateRpcBody?.p_send_key || '');
const chatId = String(body?.deliveryAddress ?? '').normalize('NFKC').trim();
const plannedFor = String(body?.plannedFor ?? '').trim();
const summary = String(body?.summary ?? '').normalize('NFKC').trim();
const completedData = String(body?.completedCallbackData ?? '').trim();
const notCompletedData = String(body?.notCompletedCallbackData ?? '').trim();
const callbackPattern = /^csp:v1:[dn]:[0-9a-f]{32}$/;
const valid = Boolean(body && typeof body === 'object' && !Array.isArray(body) &&
  body.contractVersion === 'chelsea_state_future_plan_send_begin_v1' &&
  body.telegramSendAllowed === true && String(body.planId || '') === expectedPlanId &&
  String(body.sendKey || '') === expectedSendKey && Number.isSafeInteger(Number(body.planVersion)) &&
  chatId && /^\d{4}-\d{2}-\d{2}$/.test(plannedFor) && summary &&
  callbackPattern.test(completedData) && callbackPattern.test(notCompletedData) &&
  completedData !== notCompletedData && completedData.length <= 64 && notCompletedData.length <= 64);
const formatDate = value => {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return value;
  const months = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
  return `${Number(match[3])} ${months[Number(match[2]) - 1]} ${match[1]}`;
};
const promptText = valid
  ? `План на ${formatDate(plannedFor)}: «${summary}».\n\nПолучилось выполнить?`
  : '';
const inlineKeyboard = {
  rows: [{
    row: {
      buttons: [
        { text: '✅ Выполнено', additionalFields: { callback_data: completedData } },
        { text: '❌ Не выполнено', additionalFields: { callback_data: notCompletedData } }
      ]
    }
  }]
};

return [{ json: {
  ...source,
  stateFuturePlanBeginResult: body,
  stateFuturePlanBeginValid: valid,
  stateFuturePlanTelegramSendAllowed: valid,
  stateFuturePlanSendingVersion: valid ? Number(body.planVersion) : Number(source.stateRpcBody?.p_expected_version),
  stateFuturePlanChatId: chatId,
  stateFuturePlanPromptText: promptText,
  stateFuturePlanInlineKeyboard: inlineKeyboard,
  stateFuturePlanSendError: valid
    ? ''
    : String(body?.message || body?.error?.message || body?.hint || 'future_plan_send_begin_invalid').slice(0, 2000)
} }];

'use strict';

const source = $('Code | Validate Future Plan Send Begin | FuturePlanFollowUp').item.json || {};
const incoming = $input.first()?.json || {};
const response = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const message = response?.result && typeof response.result === 'object' ? response.result : response;
const messageId = String(message?.message_id ?? '').trim();
const responseChatId = String(message?.chat?.id ?? '').trim();
const expectedChatId = String(source.stateFuturePlanChatId || '').trim();
const explicitFailure = Boolean(response?.ok === false || incoming?.ok === false || response?.error || incoming?.error);
const exactReceipt = Boolean(source.stateFuturePlanBeginValid === true && !explicitFailure &&
  /^\d+$/.test(messageId) && /^-?\d+$/.test(responseChatId) && responseChatId === expectedChatId);
const telegramDate = Number(message?.date);
const sentAt = Number.isSafeInteger(telegramDate) && telegramDate > 0
  ? new Date(telegramDate * 1000).toISOString()
  : new Date().toISOString();

return [{ json: {
  ...source,
  stateFuturePlanTelegramReceiptExact: exactReceipt,
  stateFuturePlanSendErrorCode: exactReceipt ? '' : (explicitFailure
    ? 'future_plan_telegram_rejected'
    : 'future_plan_telegram_receipt_invalid'),
  stateRpcBody: exactReceipt ? {
    p_plan_id: String(source.stateFuturePlanBeginRpcBody?.p_plan_id || ''),
    p_lease_token: String(source.stateFuturePlanBeginRpcBody?.p_lease_token || ''),
    p_expected_version: Number(source.stateFuturePlanSendingVersion),
    p_send_key: String(source.stateFuturePlanBeginRpcBody?.p_send_key || ''),
    p_chat_id: responseChatId,
    p_external_message_id: messageId,
    p_sent_at: sentAt
  } : null
} }];

'use strict';

const source = $('Code | Build Future Plan Send Complete | FuturePlanFollowUp').item.json || {};
const incoming = $input.first()?.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const valid = Boolean(body && typeof body === 'object' && !Array.isArray(body) &&
  body.contractVersion === 'chelsea_state_future_plan_send_complete_v1' &&
  String(body.planId || '') === String(source.stateRpcBody?.p_plan_id || '') &&
  body.status === 'awaiting_confirmation' && Number.isSafeInteger(Number(body.planVersion)) &&
  /^\d+$/.test(String(body.externalMessageId || '')));

return [{ json: {
  ...source,
  stateFuturePlanSendCompleted: valid,
  stateFuturePlanSendCompleteResult: body,
  stateFuturePlanSendCompleteError: valid
    ? ''
    : String(body?.message || body?.error?.message || body?.hint || 'future_plan_send_complete_invalid').slice(0, 2000)
} }];

'use strict';

const input = $input.first()?.json || {};
let source = input;
if (!source.stateFuturePlanBeginResult) {
  try { source = $('Code | Build Future Plan Send Complete | FuturePlanFollowUp').item.json || input; } catch {}
}
const ready = source.stateFuturePlanBeginValid === true && (
  source.stateFuturePlanTelegramReceiptExact !== true || source.stateFuturePlanSendCompleted === false
);
const errorCode = String(
  source.stateFuturePlanSendCompleteError || source.stateFuturePlanSendErrorCode || 'future_plan_telegram_send_uncertain'
).slice(0, 120);

return [{ json: {
  ...source,
  stateFuturePlanUncertainReady: ready,
  stateRpcBody: ready ? {
    p_plan_id: String(source.stateFuturePlanBeginRpcBody?.p_plan_id || source.stateFuturePlanBeginResult?.planId || ''),
    p_lease_token: String(source.stateFuturePlanBeginRpcBody?.p_lease_token || ''),
    p_expected_version: Number(source.stateFuturePlanSendingVersion),
    p_error_code: errorCode,
    p_error_text: errorCode
  } : null
} }];
